List METGetAttributeValueList(str _attrValue)
{
    List resultList = new List(Types::String);

    GUPAbstractPricingAttribute abstractPricingAttribute;
    GUPIPricingAttribute pricingAttribute = GUPPricingAttributeRepository::priceAttribute(this.PriceAttributeClassId, this.AttributeProviderClassId, this.AttributeName, this.TypeName);

    if (pricingAttribute is GUPAbstractPricingAttribute)
    {
        abstractPricingAttribute = pricingAttribute as GUPAbstractPricingAttribute;
    }


    if (abstractPricingAttribute /*&& abstractPricingAttribute.isMultiValue()*/)
    {
        List multiValueList = new List(Types::String);
        multiValueList = strSplit(_attrValue, ',');

        //if (abstractPricingAttribute.isHierachicalMultiValue())
        {
            ListIterator iterator = new ListIterator(multiValueList);
            while(iterator.more())
            {
                resultList.appendList(strSplit(iterator.value(), '/'));
                iterator.next();
            }
        }
        /*
        else
        {
            resultList.appendList(multiValueList);
        }
        */
    }
    else
    {
        resultList.addEnd(_attrValue);
    }

    return resultList;
}
